const GetIT = () => {
  return (
    <div className="w-full flex border-y-4 bg-stone-950 p-5">
      <h1 className="text-8xl text-stone-50 font-bold flex justify-end">
        GET IN TOUCH
      </h1>
      <div>
        <button class="bg-transparent h-full hover:bg-stone-50 text-stone-50 font-semibold hover:text-stone-950 py-2 px-4 border-4 border-stone-50 hover:border-transparent">
          Resume
        </button>
        <button class="bg-stone-50 h-full hover:bg-stone-50 text-stone-950 font-semibold hover:text-stone-50 py-2 px-4 border-4 border-stone-50 hover:border-transparent">
          Contact
        </button>
      </div>
    </div>
  );
};

export default GetIT;
